// 由 process_geojson.mjs 从 DataV GeoJSON 生成
// 保留全部顶点（不抽样）：相邻省份共享边界在源数据中坐标完全一致，投影取整后仍逐点重合，杜绝交界处空隙/双线

export const CANVAS_WIDTH = 802;
export const CANVAS_HEIGHT = 433;

export interface PolygonRing {
  outer: [number, number][];
  holes: [number, number][][];
}

export interface ProvincePath {
  name: string;
  adcode: number;
  polygons: PolygonRing[];
  isTarget: boolean;
}

export function provinceToPathData(polygon: PolygonRing): string {
  const parts: string[] = [];
  for (const ring of [polygon.outer, ...polygon.holes]) {
    if (ring.length === 0) continue;
    parts.push("M " + ring[0][0] + " " + ring[0][1] + " " + ring.slice(1).map(p => "L " + p[0] + " " + p[1]).join(" ") + " Z");
  }
  return parts.join(" ");
}

